    // diagonal = [2,2,2,2,2]
    // off-diagonal = [-1,-1,-1,-1] (subdiagonal and superdiagonal)

    std::vector<double> diag = {2.0, 2.0, 2.0, 2.0, 2.0};
    std::vector<double> subdiag = {-1.0, -1.0, -1.0, -1.0};

